mapper.sql:
SELECT DISTINCT 'USER' AS subject_type, rule.id AS conflict_rule_id, ur.abstract_user_id AS abstract_user_id, CAST(NULL AS BIGINT) AS abstract_role_id, re.biz_domain_id AS biz_domain_id, re.id AS resource_entity_id, re.resource_type AS resource_type_value, rule.first_operation_permission_id AS first_operation_permission_id, rule.second_operation_permission_id AS second_operation_permission_id FROM permission_conflict_rule rule JOIN role_resource_permission rrp_first ON rrp_first.tenant_id = rule.tenant_id AND rrp_first.operation_permission_id = rule.first_operation_permission_id AND rrp_first.delete_flag = 0 JOIN role_resource_permission rrp_second ON rrp_second.tenant_id = rule.tenant_id AND rrp_second.abstract_role_id = rrp_first.abstract_role_id AND rrp_second.resource_entity_id = rrp_first.resource_entity_id AND rrp_second.operation_permission_id = rule.second_operation_permission_id AND rrp_second.delete_flag = 0 JOIN user_role ur ON ur.tenant_id = rule.tenant_id AND ur.abstract_role_id = rrp_first.abstract_role_id AND ur.delete_flag = 0 AND (ur.valid_from IS NULL OR ur.valid_from <= CURRENT_TIMESTAMP) AND (ur.valid_to IS NULL OR ur.valid_to >= CURRENT_TIMESTAMP) JOIN abstract_role ar ON ar.tenant_id = rule.tenant_id AND ar.id = rrp_first.abstract_role_id AND ar.delete_flag = 0 JOIN resource_entity re ON re.tenant_id = rule.tenant_id AND re.id = rrp_first.resource_entity_id AND re.delete_flag = 0 WHERE rule.tenant_id = #{tenantId} AND rule.delete_flag = 0 AND (rule.resource_type_value IS NULL OR rule.resource_type_value = re.resource_type) AND (rule.biz_domain_id IS NULL OR rule.biz_domain_id = re.biz_domain_id)
AND (ar.biz_domain_id = #{bizDomainId} OR ar.biz_domain_id IS NULL) AND (re.biz_domain_id = #{bizDomainId} OR re.biz_domain_id IS NULL)
AND re.id = #{resourceEntityId}
UNION SELECT DISTINCT 'ROLE' AS subject_type, rule.id AS conflict_rule_id, CAST(NULL AS BIGINT) AS abstract_user_id, rrp_first.abstract_role_id AS abstract_role_id, re.biz_domain_id AS biz_domain_id, re.id AS resource_entity_id, re.resource_type AS resource_type_value, rule.first_operation_permission_id AS first_operation_permission_id, rule.second_operation_permission_id AS second_operation_permission_id FROM permission_conflict_rule rule JOIN role_resource_permission rrp_first ON rrp_first.tenant_id = rule.tenant_id AND rrp_first.operation_permission_id = rule.first_operation_permission_id AND rrp_first.delete_flag = 0 JOIN role_resource_permission rrp_second ON rrp_second.tenant_id = rule.tenant_id AND rrp_second.abstract_role_id = rrp_first.abstract_role_id AND rrp_second.resource_entity_id = rrp_first.resource_entity_id AND rrp_second.operation_permission_id = rule.second_operation_permission_id AND rrp_second.delete_flag = 0 JOIN abstract_role ar ON ar.tenant_id = rule.tenant_id AND ar.id = rrp_first.abstract_role_id AND ar.delete_flag = 0 JOIN resource_entity re ON re.tenant_id = rule.tenant_id AND re.id = rrp_first.resource_entity_id AND re.delete_flag = 0 WHERE rule.tenant_id = #{tenantId} AND rule.delete_flag = 0 AND (rule.resource_type_value IS NULL OR rule.resource_type_value = re.resource_type) AND (rule.biz_domain_id IS NULL OR rule.biz_domain_id = re.biz_domain_id)
AND (ar.biz_domain_id = #{bizDomainId} OR ar.biz_domain_id IS NULL) AND (re.biz_domain_id = #{bizDomainId} OR re.biz_domain_id IS NULL)
AND re.id = #{resourceEntityId}
